def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_d = 0
    opp_d = 0
    for m, o in history:
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1

    last_me, last_opp = history[-1]

    # Exploit unconditional cooperators
    if opp_d == 0:
        if my_d > 0:
            return 'D'
        else:
            if n >= 50 and n % 20 == 0:
                return 'D'
            return 'C'

    opp_rate = (n - opp_d) / n

    # Defect against heavy defectors
    recent = history[-5:] if n >= 5 else history
    recent_opp_d = sum(1 for _, o in recent if o == 'D')
    if opp_rate < 0.2 or (n >= 10 and recent_opp_d >= 4 and opp_rate < 0.5):
        return 'D'

    # Stop forgiving if two consecutive C vs D have already occurred
    for i in range(1, n):
        if (history[i][0] == 'C' and history[i][1] == 'D' and
            history[i-1][0] == 'C' and history[i-1][1] == 'D'):
            return 'D'

    # Opponent's current defection streak
    opp_streak_d = 0
    for i in range(n-1, -1, -1):
        if history[i][1] == 'D':
            opp_streak_d += 1
        else:
            break

    if opp_streak_d >= 3:
        if last_me == 'C' and last_opp == 'D':
            if n >= 2 and history[-2][0] == 'C' and history[-2][1] == 'D':
                return 'D'
            else:
                return 'C'
        elif opp_streak_d == 3:
            return 'C'
        else:
            return 'D'

    # Normal TFT with forgiveness for isolated defections
    if last_opp == 'D':
        if opp_streak_d == 1 and opp_rate > 0.8:
            return 'C'
        else:
            return 'D'
    else:
        return 'C'
